@[simp] theorem symbolLinearAlgHom_C {n : ℕ}
    (M : Matrix (PhaseVar n) (PhaseVar n) k) (c : k) :
    symbolLinearAlgHom k M (MvPolynomial.C c) = MvPolynomial.C c

theorem axisPolynomial_isHomogeneous {n N : ℕ}
    (t : PhaseVar n) {P : SymbolRing k n} (hP : P.IsHomogeneous N) :
    (axisPolynomial k t P).IsHomogeneous N

theorem symbolLinearCombination_isHomogeneous {n : ℕ}
    (M : Matrix (PhaseVar n) (PhaseVar n) k) (i : PhaseVar n) :
    (symbolLinearCombination k M i).IsHomogeneous 1

lemma commute_potentialSum_x {terms : List (D × ℕ)}
    (h : ∀ t ∈ terms, t.1 * x = x * t.1) :
    potentialSum x terms * x = x * potentialSum x terms

lemma commute_potentialSum_x_pow {terms : List (D × ℕ)}
    (h : ∀ t ∈ terms, t.1 * x = x * t.1) (r : ℕ) :
    potentialSum x terms * x ^ r = x ^ r * potentialSum x terms
